import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter class that implements a probabilistic data structure to test membership
    of elements with a specified false positive rate. The implementation uses multiple hash functions
    and a bit array to efficiently manage memory while minimizing false positives.

    Design Choices:
    - Bit array size and number of hash functions are calculated based on expected items and 
      desired false positive rate using established mathematical formulas.
    - Custom hashing is performed using SHA-256 to ensure uniform distribution.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        if expected_items <= 0:
            raise ValueError("Expected items must be a positive integer.")
        if not (0 < false_positive_rate < 1):
            raise ValueError("False positive rate must be between 0 and 1.")

        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate optimal bit array size and number of hash functions
        self.size = self._calculate_bit_array_size()
        self.hash_count = self._calculate_hash_count()

        # Initialize bit array
        self.bit_array = [0] * self.size

    def _calculate_bit_array_size(self) -> int:
        return math.ceil(-(self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2))

    def _calculate_hash_count(self) -> int:
        return max(1, int(math.ceil((self.size / self.expected_items) * math.log(2))))

    def _hashes(self, item: str) -> list:
        """Generate multiple hash values for the given item."""
        hash_values = []
        for i in range(self.hash_count):
            # Create a unique hash with a salt based on the index
            hash_value = int(hashlib.sha256(f"{item}{i}".encode()).hexdigest(), 16) % self.size
            hash_values.append(hash_value)
        return hash_values

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for hash_value in self._hashes(item):
            self.bit_array[hash_value] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom Filter."""
        return all(self.bit_array[hash_value] for hash_value in self._hashes(item))

