class BloomFilter:
    """
    A Bloom Filter class that implements a scalable and efficient probabilistic membership checking 
    structure using a custom bit manipulation strategy and dual hash algorithms for better collision 
    avoidance. 

    Design Choices:
    - The optimal size of the bit array and the number of hash functions are calculated for 
      expected items and specified false positive rate, using formulas derived from the properties of 
      the Bloom Filter.
    - A simple integer-based approach for the bit array is used instead of external libraries, 
      which facilitates lightweight and fast operations.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        if expected_items <= 0:
            raise ValueError("Expected items must be a positive integer.")
        if not (0 < false_positive_rate < 1):
            raise ValueError("False positive rate must be between 0 and 1.")

        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate optimal bit array size and number of hash functions
        self.size = self._calculate_bit_array_size()
        self.hash_count = self._calculate_hash_count()

        # Initialize bit array
        self.bit_array = 0

    def _calculate_bit_array_size(self) -> int:
        return math.ceil(-(self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2))

    def _calculate_hash_count(self) -> int:
        return max(1, int(math.ceil((self.size / self.expected_items) * math.log(2))))

    def _hash(self, item: str, seed: int) -> int:
        """Generate a hash value for the given item with a seed for uniqueness."""
        hash_value = int(hashlib.md5(f"{item}{seed}".encode()).hexdigest(), 16)
        return hash_value % self.size

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for i in range(self.hash_count):
            hash_value = self._hash(item, i)
            self.bit_array |= (1 << hash_value)

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom Filter."""
        return all((self.bit_array & (1 << self._hash(item, i))) != 0 for i in range(self.hash_count))
